-4beb-8c34-60df4f81dfbd\",\"displayName\":\"TOTAL PRESCALED QTY\",\"exclude\":false,\"datatype\":\"number\",\"aggrRule\":\"none\",\"uiOptions\":{\"prepColumnName\":\"TOTAL_PRESCALED_QTY_23f0abe3-5be7-4beb-8c34-60df4f81dfbd\",\"originalColumnName\":\"TOTAL_PRESCALED_QTY\",\"isUserCalculation\":true,\"isApplied\":false,\"transformEngine\":\"bis\"},\"sourceexpr\":\"\\\"TOTAL_PRESCALED_QTY_23f0abe3-5be7-4beb-8c34-60df4f81dfbd\\\"\",\"errorStatus\":\"\"}],\"options\":{\"outputColumnDataType\":\"number\",\"outputColumnAggrRule\":\"none\",\"outputColumnHidden\":false,\"outputColumnDisplayName\":\"TOTAL PRESCALED QTY\",\"isEditorValid\":false,\"afterColumn\":\"TOTAL_PRESCALED_QTY\"},\"applied\":true,\"inplace\":true,\"rename\":true,\"allowEdit\":true,\"generatesOutputColumns\":true,\"unsavedTransform\":false,\"parentId\":\"24\"},{\"id\":\"26\",\"type\":\"RENAME_COLUMN\",\"sourceColumns\":[\"TOTAL_DISTRO_QTY\"],\"expressionSourceColumns\":[\"TOTAL_DISTRO_QTY\"],\"outputColumns\":[{\"name\":\"TOTAL_DISTRO_QTY_fde1872a-792c-4cbc-91b1-1ad7662ee763\",\"displayName\":\"TOTAL DISTRO QTY\",\"exclude\":false,\"datatype\":\"number\",\"aggrRule\":\"none\",\"uiOptions\":{\"prepColumnName\":\"TOTAL_DISTRO_QTY_fde1872a-792c-4cbc-91b1-1ad7662ee763\",\"originalColumnName\":\"TOTAL_DISTRO_QTY\",\"isUserCalculation\":true,\"isApplied\":false,\"transformEngine\":\"bis\"},\"sourceexpr\":\"\\\"TOTAL_DISTRO_QTY_fde1872a-792c-4cbc-91b1-1ad7662ee763\\\"\",\"errorStatus\":\"\"}],\"options\":{\"outputColumnDataType\":\"number\",\"outputColumnAggrRule\":\"none\",\"outputColumnHidden\":false,\"outputColumnDisplayName\":\"TOTAL DISTRO QTY\",\"isEditorValid\":false,\"afterColumn\":\"TOTAL_DISTRO_QTY\"},\"applied\":true,\"inplace\":true,\"rename\":true,\"allowEdit\":true,\"generatesOutputColumns\":true,\"unsavedTransform\":false,\"parentId\":\"25\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT \\n        ah.alloc_no, \\n        'A'                           doc_type, \\n        NULL                          ext_ref_no, \\n        ah.status, \\n        ah.release_date,\\n        ah.item, \\n        im.item_desc,\\n        im.pack_ind, \\n        SUM(pi.pack_qty)              total_comp_qty_pack, \\n        ah.context_type               context_type, \\n        ah.context_value              context_value,\\n        w.physical_wh                 source_wh, \\n        ad.to_loc, \\n        s.store_name, \\n        nvl(ad.qty_allocated, 0)      total_allocated_qty, \\n        nvl(ad.qty_transferred, 0)    total_shipped_qty_alloc, \\n        nvl(ad.qty_received, 0)       total_received_qty_alloc,\\n        nvl(ad.qty_cancelled, 0)      total_cancelled_qty, \\n        nvl(ad.qty_prescaled, 0)      total_prescaled_qty, \\n        nvl(ad.qty_distro, 0)         total_distro_qty \\n    FROM \\n        rds_wv_alloc_header              ah, \\n        rds_wv_alloc_detail              ad,\\n        rds_wv_item_master               im,\\n        rds_wv_packitem                  pi,\\n        rds_wv_store                     s, \\n        rds_wv_wh                        w\\n    WHERE \\n        ah.alloc_no = ad.alloc_no\\n        AND ah.item = im.item \\n        AND im.item = pi.pack_no (+)\\n        AND ad.to_loc = s.store \\n        AND ah.wh = w.wh\\n\\t\\tGROUP BY \\n        ah.alloc_no,\\n        ah.status, \\n        ah.release_date,\\n        ah.item,\\n        im.item_desc,\\n        im.pack_ind, \\n        w.physical_wh, \\n        ad.to_loc, \\n        s.store_name, \\n        ad.qty_allocated,\\n        ad.qty_transferred,\\n        ad.qty_received, \\n        ad.qty_cancelled, \\n        ad.qty_prescaled, \\n        ad.qty_distro, \\n        ah.context_type, \\n        ah.context_value;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-16T10:53:34.903+0000","connection-namespace":"OracleRetailCloudAdmin@deloitte.com","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_418'","parent-namespace":"ReCommon","parent-name":"RPT_418","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_418'"}
